// Package mcp — intent handlers.
//
// Intents are higher-level MCP tools that compose multiple endpoint calls
// or expose curated recipe commands with useful flag defaults.
// Rather than forcing an agent to stitch primitives like get_thread +
// create_issue + link_attachment, a single create_issue_from_thread tool
// accepts the top-level input, calls each endpoint in sequence, resolves
// bindings between steps, and returns the final captured value.
//
// Each intent is emitted as a handler registered alongside (or in place of,
// when MCP.EndpointTools == "hidden") the raw endpoint-mirror tools.

package mcp

import (
	"context"
	"fmt"
	"os"
	"strings"

	mcplib "github.com/mark3labs/mcp-go/mcp"
	"github.com/mark3labs/mcp-go/server"
	"github.com/mvanhorn/printing-press-library/library/commerce/square/internal/cli"
	"github.com/mvanhorn/printing-press-library/library/commerce/square/internal/mcp/bound"
	"github.com/mvanhorn/printing-press-library/library/commerce/square/internal/mcp/cobratree"
)

// RegisterIntents adds generated intent tools to the MCP server.
// This is called from RegisterTools when spec intents or recipe-lifted intents exist.
func RegisterIntents(s *server.MCPServer) {
	if recipeTargetExposed([]string{"customer", "timeline"}) {
		s.AddTool(
			mcplib.NewTool("trace_a_customer",
				mcplib.WithDescription("Assemble connected customer activity into one chronological record."),
				mcplib.WithString("slug", mcplib.Required(), mcplib.Description("Override the recipe's positional slug value.")),
			),
			handleTraceACustomer,
		)
	}
}

// handleTraceACustomer runs the trace_a_customer recipe intent: Assemble connected customer activity into one chronological record.
func handleTraceACustomer(ctx context.Context, req mcplib.CallToolRequest) (*mcplib.CallToolResult, error) {
	if recipeCLIPathErr != nil {
		return mcplib.NewToolResultError(fmt.Sprintf("companion CLI binary not found: %v", recipeCLIPathErr)), nil
	}

	if !recipeTargetExposed([]string{"customer", "timeline"}) {
		return mcplib.NewToolResultError("tool is not available"), nil
	}

	input := req.GetArguments()
	args := []string{}
	args = append(args, "customer")
	args = append(args, "timeline")
	var missingSlug bool
	args, missingSlug = appendRecipePositional(args, input["slug"], true)
	if missingSlug {
		return mcplib.NewToolResultError("slug is required"), nil
	}
	args = append(args, "--agent")

	out, err := cobratree.RunCLICommand(ctx, recipeCLIPath, args)
	if err != nil {
		return mcplib.NewToolResultError(err.Error()), nil
	}
	return mcplib.NewToolResultText(bound.Text(out)), nil
}

var (
	recipeCLIPath    string
	recipeCLIPathErr error
)

func init() {
	recipeCLIPath, recipeCLIPathErr = cobratree.SiblingCLIPath()
}

// recipeCommandRoot is the live Cobra tree consulted for a recipe's target
// command: its hidden / mcp:hidden / read-only annotations. Recipe text does
// not carry these; the live command does.
var recipeCommandRoot = cli.RootCmd

// recipeTargetExposed reports whether the command a recipe wraps may be surfaced
// and run over MCP right now. When the recipe's target resolves to an in-tree
// command, that command must not be hidden (itself or an ancestor, Cobra-hidden
// or mcp:hidden). While the MCP read-only switch is on, the recipe is withheld
// unless its target is annotated mcp:read-only or mcp:local-write. A recipe whose
// target does not resolve to an in-tree command is not blocked when the read-only
// switch is off, but it is withheld under read-only.
func recipeTargetExposed(path []string) bool {
	if recipeCommandRoot == nil {
		return true
	}
	cmd := cobratree.CommandAtPath(recipeCommandRoot(), recipeCommandPath(path))
	if cmd != nil && !cobratree.CommandExposableOverMCP(cmd) {
		return false
	}
	if os.Getenv("SQUARE_MCP_READ_ONLY") == "1" && !cobratree.CommandAllowedUnderMCPReadOnly(cmd) {
		return false
	}
	return true
}

// recipeCommandPath keeps the Cobra command words. Static flags such as
// --json are stored on the same slice and are not part of the command path.
func recipeCommandPath(path []string) []string {
	out := make([]string, 0, len(path))
	for _, token := range path {
		if token == "" || strings.HasPrefix(token, "-") {
			break
		}
		out = append(out, token)
	}
	return out
}

func appendRecipePositional(args []string, value any, required bool) ([]string, bool) {
	selected := recipeValueString(value)
	if selected == "" {
		return args, required
	}
	return append(args, selected), false
}

func appendRecipeStringFlag(args []string, name string, value any, defaultValue string, required bool, useEquals bool) ([]string, bool) {
	selected := defaultValue
	if value != nil {
		selected = recipeValueString(value)
	}
	if selected == "" {
		return args, required
	}
	if useEquals {
		return append(args, "--"+name+"="+selected), false
	}
	return append(args, "--"+name, selected), false
}

func appendRecipeBoolFlag(args []string, name string, value any, defaultValue bool) []string {
	selected := defaultValue
	if v, ok := value.(bool); ok {
		selected = v
	}
	if selected {
		return append(args, "--"+name)
	}
	return args
}

func recipeValueString(value any) string {
	switch v := value.(type) {
	case string:
		return strings.TrimSpace(v)
	case float64:
		return formatMCPParamValue(v)
	case bool:
		if v {
			return "true"
		}
		return "false"
	default:
		if value == nil {
			return ""
		}
		return fmt.Sprintf("%v", value)
	}
}
